contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient balance");

        // read before-values via public surface
        uint256 clpBefore = IERC20(c.clpToken()).balanceOf(address(c));
        bool shutdown = c.isCvxShutdown();

        bool reverted;
        try c.depositAndStake(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 clpAfter = IERC20(c.clpToken()).balanceOf(address(c));

        // General rule: if the pool is shutdown, depositAndStake must not revert and must not change the CLP balance.
        // If not shutdown, either it reverted or the CLP balance did not increase (since tokens were moved out).
        assert(shutdown ? (!reverted && clpAfter == clpBefore) : reverted || clpAfter <= clpBefore);
    }

    receive() external payable {}
}

