contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOperator, uint32 pId, address token, address rewards) public {
        // caller just needs to be different from the owner (and thus not the operator unless operator == owner).
        // Use a caller that is guaranteed not to be owner nor operator for a fresh C: address(this) is owner,
        // and we restrict caller to be neither address(this) nor c.operator().
        require(caller != address(this), "caller must not be owner");
        require(caller != c.owner(), "caller must not be owner");
        require(caller != c.operator(), "caller must not be operator");

        // Snapshot observable state before the calls.
        address beforeOperator = c.operator();
        address beforeRecipient = c.rewardsRecipient();
        (address beforeCvxToken, address beforeCvxRewards, uint32 beforePId) = c.cvxPoolInfo();

        // 1. setCvxPoolInfo must revert for non-owner.
        bool revertedSetCvx;
        try c.setCvxPoolInfo(pId, token, rewards) {
            revertedSetCvx = false;
        } catch {
            revertedSetCvx = true;
        }

        // 2. setOperator must revert for non-owner.
        bool revertedSetOperator;
        try c.setOperator(newOperator) {
            revertedSetOperator = false;
        } catch {
            revertedSetOperator = true;
        }

        // 3. setRewardsRecipient must revert for non-owner.
        bool revertedSetRewardsRecipient;
        try c.setRewardsRecipient(newOperator) {
            revertedSetRewardsRecipient = false;
        } catch {
            revertedSetRewardsRecipient = true;
        }

        // 4. recoverToken must revert for non-owner when the token transfer would succeed.
        bool revertedRecoverToken;
        try c.recoverToken(token, newOperator, 0) {
            revertedRecoverToken = false;
        } catch {
            revertedRecoverToken = true;
        }

        // None of these calls should have changed owner-only observable state.
        (address afterCvxToken, address afterCvxRewards, uint32 afterPId) = c.cvxPoolInfo();

        assert(
            revertedSetCvx &&
                revertedSetOperator &&
                revertedSetRewardsRecipient &&
                revertedRecoverToken &&
                c.operator() == beforeOperator &&
                c.rewardsRecipient() == beforeRecipient &&
                afterCvxToken == beforeCvxToken &&
                afterCvxRewards == beforeCvxRewards &&
                afterPId == beforePId
        );
    }
}

