        try c.depositAndStake(amount) { depositAndStakeReverted = false; } catch { depositAndStakeReverted = true; }

        bool withdrawAndUnwrapReverted;
        try c.withdrawAndUnwrap(amount, claim, to) { withdrawAndUnwrapReverted = false; } catch { withdrawAndUnwrapReverted = true; }

        bool withdrawAllAndUnwrapReverted;
        try c.withdrawAllAndUnwrap(claim, sendToOperator) { withdrawAllAndUnwrapReverted = false; } catch { withdrawAllAndUnwrapReverted = true; }

        bool recoverTokenReverted;
        try c.recoverToken(token, to, amount) { recoverTokenReverted = false; } catch { recoverTokenReverted = true; }

        bool cvxShutdown = c.isCvxShutdown();

        assert(
