contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint256 amount, uint32 pId, address token, address rewardsAddress) public payable {
        require(caller != address(0), "caller zero");

        // Make sure the caller is not the operator (and if owner is a different address,
        // that it is also not the operator). We only want to test non-operator callers.
        require(caller != c.operator(), "caller is operator");
        require(caller != c.owner(), "caller is owner");

        // Set up the CVX pool info through the owner (the test contract)
        c.setCvxPoolInfo(pId, token, rewardsAddress);

        // Record the pool info before the attempted deposit
        uint32 beforePId = c.cvxPoolInfo().pId;
        address beforeToken = c.cvxPoolInfo().token;
        address beforeRewards = c.cvxPoolInfo().rewards;

        // Attempt depositAndStake as a non-operator caller; should revert with NotOperator
        bool reverted;
        try c.depositAndStake(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Verify pool info is unchanged
        CvxPoolInfo memory infoAfter = c.cvxPoolInfo();
        bool stateUnchanged = (infoAfter.pId == beforePId &&
                               infoAfter.token == beforeToken &&
                               infoAfter.rewards == beforeRewards);

        assert(reverted && stateUnchanged);
    }

    receive() external payable {}
}

