    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 amount) public {
        require(to != address(0));

        uint256 beforeRecipient = c.clpToken().balanceOf(to);
        uint256 beforeContract = c.clpToken().balanceOf(address(c));
        require(amount <= beforeContract);

        c.withdrawAndUnwrap(amount, false, to);

        uint256 afterRecipient = c.clpToken().balanceOf(to);
        uint256 afterContract = c.clpToken().balanceOf(address(c));

        assert(
            afterRecipient == beforeRecipient + amount &&
            afterContract == beforeContract - amount
        );
    }
}

