contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address token, address to, uint256 amount) public {
        require(token != address(0), "token must not be zero");
        require(to != address(0), "to must not be zero");

        uint256 beforeBalance = IERC20(token).balanceOf(address(c));
        uint256 beforeToBalance = IERC20(token).balanceOf(to);

        bool reverted;
        try c.recoverToken(token, to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 afterBalance = IERC20(token).balanceOf(address(c));
            uint256 afterToBalance = IERC20(token).balanceOf(to);
            assert(afterBalance == beforeBalance - amount);
            assert(afterToBalance == beforeToBalance + amount);
        } else {
            assert(beforeBalance == IERC20(token).balanceOf(address(c)));
        }
    }

    receive() external payable {}
}

