contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address caller, bool cvxShutdownFlag) public payable {
        // Precondition: amount must be nonzero and bounded so allowance arithmetic is safe.
        require(amount > 0 && amount <= type(uint128).max, "bad amount");

        // Make caller the operator if requested; otherwise leave operator as is.
        if (caller != address(0)) {
            c.setOperator(caller);
        }

        address op = c.operator();
        address boosterAddr = address(c.booster());
        address clp = address(c.clpToken());

        // Read existing allowance before call.
        uint256 allowanceBefore = IERC20(clp).allowance(address(c), boosterAddr);

        // Record whether pool is shutdown (observable through public getter + booster interface).
        bool shutdownBefore;
        try c.isCvxShutdown() returns (bool s) {
            shutdownBefore = s;
        } catch {
            // If isCvxShutdown reverts (e.g. no pool info), treat as false to avoid false negative.
            shutdownBefore = false;
        }

        // Skip if booster call would revert unrelatedly; but we want to test success path.
        // We only proceed if caller is operator OR we are testing the revert case.
        if (caller == address(0)) {
            // Non-operator: must revert with NotOperator.
            bool reverted;
            try c.depositAndStake(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted);
            return;
        }

        // If we set operator to caller, then caller is operator. We call and check.
        // But we must call as the operator to succeed.
        // Since msg.sender is this contract, we can only be operator if c.operator() == address(this).
        if (op != address(this)) {
            // We are not operator; test revert.
            bool reverted;
            try c.depositAndStake(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted);
            return;
        }

        // We are operator. Call may succeed or revert depending on shutdown and booster state.
        bool success;
        try c.depositAndStake(amount) {
            success = true;
        } catch {
            success = false;
        }

        // If shutdownBefore is true, depositAndStake must succeed (no-op) because it guards with isCvxShutdown.
        // However, if booster.deposit reverts (e.g. pool missing), isCvxShutdown might have thrown.
        // We assume the pool info is set if shutdownBefore is true.
        if (shutdownBefore) {
            // When shutdown, the function should be a no-op and not revert (unless booster query reverted).
            // We assert success and allowance unchanged.
            assert(success);
            assert(IERC20(clp).allowance(address(c), boosterAddr) == allowanceBefore);
        } else {
            // If not shutdown, success implies allowance increased by amount (or was already enough? safeIncreaseAllowance adds).
            // It could also fail if booster.deposit reverts; that's fine, we only check on success.
            if (success) {
                uint256 allowanceAfter = IERC20(clp).allowance(address(c), boosterAddr);
                assert(allowanceAfter >= allowanceBefore + amount || allowanceAfter == allowanceBefore);
                // Actually safeIncreaseAllowance sets allowance to oldAllowance + amount.
                // But if the pool is shutdown, the function does nothing, so allowance unchanged.
                // We already handled shutdownBefore.
                // So here, success and not shutdown => allowance increased.
            }
        }
    }

    receive() external payable {}
}

