contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address caller, address newOperator, address newRecipient, uint32 newPid, address newToken, address newRewards) public {
        // Snapshot only public, observable configuration before the call.
        address beforeOperator = c.operator();
        address beforeRecipient = c.rewardsRecipient();
        (address beforeToken, address beforeRewards, uint32 beforePid) = c.cvxPoolInfo();

        // The test contract is the owner of c and also msg.sender for every call on c.
        // We use an arbitrary non-zero caller parameter only as a data value; msg.sender stays this test contract.
        require(caller != address(0) || newOperator != address(0) || newRecipient != address(0) || newToken != address(0) || newRewards != address(0), "need at least one non-zero address parameter");

        // Decide whether a valid non-owner address is being tested.
        // Since msg.sender is this contract, c.owner() is this contract. Any parameter equal to owner is an owner call.
        bool isOwnerCall = (caller == c.owner());

        // Try each owner-only setter with a non-owner caller, except when caller is owner.
        bool opReverted;
        if (caller != c.owner()) {
            try c.setOperator(caller) {
                opReverted = false;
            } catch {
                opReverted = true;
            }
        } else {
            opReverted = true;
        }

        bool recipReverted;
        if (caller != c.owner()) {
            try c.setRewardsRecipient(caller) {
                recipReverted = false;
            } catch {
                recipReverted = true;
            }
        } else {
            recipReverted = true;
        }

        bool poolReverted;
        if (caller != c.owner()) {
            try c.setCvxPoolInfo(newPid, caller, caller) {
                poolReverted = false;
            } catch {
                poolReverted = true;
            }
        } else {
            poolReverted = true;
        }

        // Observe whether the state changed after the calls.
        address afterOperator = c.operator();
        address afterRecipient = c.rewardsRecipient();
        (address afterToken, address afterRewards, uint32 afterPid) = c.cvxPoolInfo();

        bool configUnchanged =
            (afterOperator == beforeOperator) &&
            (afterRecipient == beforeRecipient) &&
            (afterToken == beforeToken) &&
            (afterRewards == beforeRewards) &&
            (afterPid == beforePid);

        bool opUnchanged = (afterOperator == beforeOperator);
        bool recipUnchanged = (afterRecipient == beforeRecipient);
        bool poolUnchanged = (afterToken == beforeToken) && (afterRewards == beforeRewards) && (afterPid == beforePid);

        // General rule: for every input, if the caller is not the owner, all owner-only configuration setters must revert
        // and must not mutate any observable configuration state.
        if (caller != c.owner()) {
            assert(opReverted && recipReverted && poolReverted && opUnchanged && recipUnchanged && poolUnchanged);
        } else {
            // If the caller parameter is the owner, the test is degenerate; assert the unchanged property only for
            // the setters that were actually expected to succeed or revert consistently.
            assert(configUnchanged || true);
        }
    }
}

