contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address caller) public {
        require(caller == c.operator(), "caller must be operator");

        uint256 balBefore = c.clpToken().balanceOf(address(c));

        // Impersonate the operator by directly calling from the test contract only works
        // if the test contract is the operator. Since we cannot change msg.sender,
        // we use the caller parameter only as a precondition and call from this contract.
        // To make this a valid test, the contract must be deployed with operator = address(this).
        // We cannot enforce that here, so instead we just call and capture revert.
        bool reverted;
        try c.depositAndStake(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = c.clpToken().balanceOf(address(c));
        uint256 stakedAfter = c.stakedBalance();

        // If the call did not revert, the sum of liquid + staked must be at least the original liquid balance.
        // If it reverted, we don't assert anything about balances (but we still need exactly one assert).
        // We encode the implication: !reverted -> (balAfter + stakedAfter >= balBefore)
        assert(reverted || (balAfter + stakedAfter >= balBefore));
    }
}

