contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 amount,
        address caller,
        uint256 shutdownFlag
    ) public payable {
        require(amount > 0, "amount must be positive");
        require(caller != address(0), "caller must not be zero");

        // No ETH is needed for depositAndStake; keep the function payable only to satisfy the template if needed.

        uint256 beforeStaked = c.stakedBalance();
        uint256 beforeTokenBal = address(c.clpToken()) != address(0)
            ? c.clpToken().balanceOf(address(c))
            : 0;

        bool shutdown;
        try c.isCvxShutdown() returns (bool s) {
            shutdown = s;
        } catch {
            shutdown = (shutdownFlag % 2 == 1);
        }

        // Only attempt depositAndStake when the caller is the stored operator,
        // because the rule concerns operator-authorized deposits.
        address op = c.operator();
        bool attempted = false;
        bool reverted = false;
        try c.depositAndStake(amount) {
            attempted = true;
        } catch {
            reverted = true;
        }

        uint256 afterStaked = c.stakedBalance();
        uint256 afterTokenBal = address(c.clpToken()) != address(0)
            ? c.clpToken().balanceOf(address(c))
            : 0;

        if (msg.sender != op) {
            // Non-operator calls must always revert with NotOperator.
            assert(reverted && !attempted);
        } else {
            // For the operator:
            // - If the pool is shutdown, deposit is skipped and no revert should occur.
            // - If not shutdown and the contract cannot cover the approved amount, deposit must revert.
            // - Otherwise it must succeed and staked balance must not decrease.
            if (shutdown) {
                assert(!reverted && attempted);
                assert(afterStaked == beforeStaked);
            } else if (beforeTokenBal < amount) {
                assert(reverted && !attempted);
            } else {
                assert(!reverted && attempted);
                assert(afterStaked >= beforeStaked);
            }
        }
    }

    receive() external payable {}
}

